* Stimulus
Vin vin 0 dc 0.9 ac 1 pulse(0.5 1.3 10n 1n 1n 1u 2u)

.control
  * 1. DC Operating Point
  op
  let power = -i(VDD) * 1.8
  print power

  * 2. AC Analysis (Extracting Open-Loop from Closed-Loop)
  ac dec 100 1 1G
  let Vd = v(vin) - v(vout)
  let Aol = v(vout) / Vd
  let Aol_db = 20 * log10(mag(Aol))
  let Aol_phase = 180/PI * cph(Aol)

  meas ac dc_gain find Aol_db at=10
  meas ac fun when Aol_db=0 fall=1
  meas ac phase_at_fun find Aol_phase when Aol_db=0 fall=1
  let PM = 180 + phase_at_fun
  print PM

  * 3. Transient Analysis for Slew Rate
  tran 1n 2u
  meas tran t_rise trig v(vout) val=0.6 rise=1 targ v(vout) val=1.2 rise=1
  let slew_rate_rise = (1.2 - 0.6) / t_rise
  print slew_rate_rise

  meas tran t_fall trig v(vout) val=1.2 fall=1 targ v(vout) val=0.6 fall=1
  let slew_rate_fall = (1.2 - 0.6) / t_fall
  print slew_rate_fall

  quit
.endc

